UPDATE companies SET description='York Haven Fabricators (YHFAB) operates from York Haven, Pennsylvania. Founded in 1998 by Henry Shefet as a division of Daisy Data (established 1982), it became independent in 2000 and added 40,000 square feet in 2001. In 2025, S&W Metal Products—a Pennsylvania fabricator since 1946—acquired the company, merging over 100 years of manufacturing experience.

YHFAB delivers custom metal fabrication and CNC machining from a 160,000-square-foot facility with 109+ employees and 160+ machines. Integrated services include fiber laser cutting, CNC press brake forming, robotic bending, turret punching, MIG/TIG/spot and robotic welding, plate rolling, finishing, and 5-axis milling and live-tooling turning. The shop runs prototype to high-volume production, shipping 16,000+ line items annually, with in-house engineering, CAD/CAM programming, and design-for-manufacture support.

Customers span commercial, service, automotive, lighting, energy, material handling, factory automation, electronics enclosures, military, medical, packaging, and transportation markets. Examples include parts for material handling and automation systems, automotive Tier 1/2 components, commercial lighting fixtures, electronic enclosures for industrial and utility use, and critical oil, gas, and renewable energy parts.

The company cites its single-facility integration of fabrication, machining, welding, and finishing, an ISO 9001:2015 system (certified since 2012), advanced automation (robotic welding, high-throughput laser loading), real-time MRP tracking, and inspection via Virtek LaserQC (±0.002 in) and FARO Edge CMM (±0.0014 in) as key differentiators.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Fiber laser cutting", "CNC press brake forming", "Robotic bending", "CNC turret punching", "MIG welding", "TIG welding", "Spot welding", "Robotic welding", "Surface finishing", "Polishing", "Plate rolling", "CNC milling (vertical, horizontal, 5-axis)", "CNC turning (multi-axis, live tooling)", "Design for manufacture engineering", "CNC programming", "Solid modeling", "First article inspection", "Virtek LaserQC inspection", "FARO Edge CMM inspection"], "industries": ["Energy", "Commercial", "Service", "Automotive", "Lighting", "Material Handling", "Factory Automation", "Electronics Enclosures", "Military", "Medical Devices", "Packaging", "Transportation", "Oil and Gas", "Renewable Energy"], "materials": [], "equipment": ["Amada CNC turret punch", "Amada press brake", "Amada flat laser equipment", "High-throughput loading/unloading automation", "Robotic welding cells", "Virtek LaserQC Inspection System", "FARO Edge Coordinate Measuring Machine", "Starrett Granite Slabs", "Mitutoyo calibrated height gauges", "Fowler calibrated height gauges"], "volume": "Prototype to high-volume production runs; 16,000+ annual line items shipped", "lead_time": "", "tolerances": "\u00b10.002 inches (Virtek LaserQC), \u00b10.0014 inches (FARO Edge CMM)", "built_on": ["Single integrated facility combining sheet metal fabrication, heavy gauge forming, welding, CNC machining, and finishing", "In-house engineering with design-for-manufacture, CAD/CAM programming, and real-time MRP tracking", "Robotic welding cells and high-throughput laser loading/unloading automation for repeatable high-volume quality", "Virtek LaserQC non-contact inspection holding \u00b10.002 inch tolerances and FARO Edge CMM achieving \u00b10.0014 inch accuracy", "ISO 9001:2015 certified quality system since 2012"], "facts_used": ["Founded 1998 by Henry Shefet as division of Daisy Data -> /about-us", "Became independent company in 2000 -> /about-us", "Facility expansion of 40,000 sq ft in 2001 -> /about-us", "Acquired by S&W Metal Products in 2025 -> /about-us", "Headquarters York Haven, Pennsylvania -> /about-us, /", "160,000 sq ft facility -> /", "109+ employees -> /", "160+ pieces of production equipment -> /", "16,000+ annual line items shipped -> /", "108+ combined years of business -> /", "ISO 9001:2015 certified since 2012 -> /quality", "Capabilities: laser cutting, CNC forming, turret punching, welding, robotic welding, finishing, rolling, CNC machining -> /capabilities, /", "Industries served: energy, commercial, automotive, lighting, material handling, factory automation, electronics enclosures, military, medical, packaging, transportation -> /, /about-us", "Equipment: Amada CNC turret punch, press brake, flat laser; robotic welding cells; Virtek LaserQC; FARO Edge CMM; Starrett Granite Slabs; Mitutoyo/Fowler height gauges -> /about-us, /quality", "Tolerances: \u00b10.002 in (Virtek), \u00b10.0014 in (FARO) -> /quality", "Volume: prototype to high-volume production runs -> /capabilities", "In-house engineering, CAD/CAM programming, design-for-manufacture -> /capabilities, /", "Real-time MRP tracking -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "York Haven Fabricators, Inc. (YHFAB) is a state-of-the-art sheet metal fabricator and machining company.", "founded_year": "1998", "employee_count": "109+", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='york-haven-fabricators' AND approved AND profile IS NULL;
UPDATE companies SET description='Founded in 1985, York Imperial Plastics is a second-generation family-owned and operated plastic injection molding facility in York, Pennsylvania. The company began as a custom molding operation and has since expanded into a full-service provider of tooling transfer, design, and production.

The company runs an all-inclusive custom plastic injection molding operation, offering services from prototype through high-volume production. Its capabilities include mold transfer and rework — with over 500 successful transfers since 1985 — multi-cavity high-production tool design, master unit die (MUD) capability, in-house assembly and packaging, and daily direct shipping. Quality processes cover APQP, PPAP, first-article inspection, CMM and optical measurement, color spectrophotometry, statistical process control, and moisture analysis.

York Imperial serves manufacturers that need custom plastic injection molded parts, tooling transfer, or turnkey assembly and shipping. Customers include those requiring rework or modification of existing tools, as well as companies seeking a single source for prototype-to-production molding, value-added assembly, and direct delivery.

The company differentiates itself through a made-in-America tool warranty on every tool it builds, ISO 9001 certification, and a quality culture that makes quality every employee''s responsibility. Its founding family''s values remain central, emphasizing strong partnerships and continuous improvement across all operations.', certifications=ARRAY['ISO 9001']::text[], profile='{"capabilities": ["Plastic injection molding", "Mold transfer and rework", "Tooling design and construction (multi-cavity, high production)", "Master unit die (MUD) capability", "Product assembly", "Packaging", "In-house shipping / direct shipping", "Advanced Product Quality Planning (APQP)", "Production Part Approval Process (PPAP)", "First Article Inspection (FAI)", "Coordinate Measuring Machine (CMM) inspection", "Optical measuring (OGP)", "Color spectrophotometry", "Statistical Process Control (SPC)", "Moisture analysis", "Made in America Tool Warranty"], "industries": [], "materials": [], "equipment": ["Coordinate Measuring Machine (CMM)", "Optical measuring system (OGP)", "Color spectrophotometer", "Moisture analyzer"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Over 500 successful mold transfers since 1985", "Made in America Tool Warranty on every tool built in-house", "Full-service in-house shipping with daily direct shipping", "ISO 9001 certified quality system with APQP, PPAP, FAI, CMM, and optical inspection", "Second-generation family-owned operation emphasizing strong family values"], "facts_used": ["Founded in 1985 -> db", "Second-generation family-owned & operated -> /", "Located in York, Pennsylvania -> /", "All-inclusive custom plastic injection molding operation -> /", "Over 500 successful mold transfers since 1985 -> db", "Specializes in execution of transfer tooling including rework and modifications -> db", "Multi-cavity high production tool design -> db", "Master unit die capability -> db", "Product assembly & packaging -> db", "Full Service In-House Shipping / Direct Shipping daily -> /", "ISO 9001 certified company -> /quality", "Quality processes: APQP, PPAP, FAI, CMM, Optical measuring (OGP), Color Spectrophotometer, SPC, Moisture Analyzing -> /quality", "Made in America Tool Warranty provided with every tool built by York Imperial Plastics -> /", "From prototype to production and beyond -> /", "Hiring for 2nd & 3rd shift Machine Operators -> /", "Over 34 years of injection molding experience (as of 2023) -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We are an all-inclusive custom plastic injection molding operation", "founded_year": "1985", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='york-imperial-plastics-inc' AND approved AND profile IS NULL;
